  ...
  return;
}
yield {type: 'text', ...};      // tail = 2 statements
yield {type: 'stop', ...};
```

tail=2 > 0, wrapped=5 ≥ 4, 5 > 2 → flagged. Fix per rule: `if (!(round === 2)) { ...tail... }` — no wait, "flip to `if (!(…))` guarding the tail and let the happy path run flat":

```ts
if (round === 2) {
  ...   (the wrapped round-2 path)
  return;
}
// happy path flat:
yield {type: 'text', ...};
yield {type: 'stop', ...};
